from __future__ import annotations

from typing import Any


def flatten(x: Any) -> list[Any]:
    """Flatten arbitrarily nested lists and tuples into one flat list, in order.

    Strings, bytes and dicts are treated as leaves and are never split apart.
    """
    out: list[Any] = []

    def _flatten(value: Any) -> None:
        if isinstance(value, (list, tuple)):
            for item in value:
                _flatten(item)
        else:
            out.append(value)

    _flatten(x)
    return out
